private GcsUtil buildMockGcsUtil() throws IOException {
    GcsUtil mockGcsUtil = Mockito.mock(GcsUtil.class);
    // Any request to open gets a new bogus channel
    Mockito.when(mockGcsUtil.open(Mockito.any(GcsPath.class))).thenReturn(new EmptySeekableByteChannel());
    // Any request for expansion gets a single bogus URL
    // after we first run the expansion code (which will generally
    // return no results, which causes a crash we aren't testing)
    Mockito.when(mockGcsUtil.expand(Mockito.any(GcsPath.class))).thenReturn(Arrays.asList(GcsPath.fromUri("gs://bucket/foo")));
    return mockGcsUtil;
}

