@Test
public void testUpdatedJobThrowsException() throws Exception {
    expectedThrown.expect(DataflowJobUpdatedException.class);
    expectedThrown.expect(DataflowJobExceptionMatcher.expectJob(JobIdMatcher.expectJobId("testUpdatedJob-jobId")));
    expectedThrown.expect(ReplacedByJobMatcher.expectReplacedBy(JobIdMatcher.expectJobId("testUpdatedJob-replacedByJobId")));
    DataflowPipelineJob job = createMockJob("testUpdatedJob-projectId", "testUpdatedJob-jobId", State.UPDATED);
    DataflowPipelineJob replacedByJob = createMockJob("testUpdatedJob-projectId", "testUpdatedJob-replacedByJobId", State.DONE);
