@Test(timeout = 5000)
public void workProgressUpdaterAdaptsProgressInterval() throws Exception {
    // Mock that the next reportProgress call will return a response that asks
    // us to truncate the task at index 3, and the next two will not ask us to
    // truncate at all.
    when(workUnitClient.reportWorkItemStatus(any(WorkItemStatus.class))).thenReturn(generateServiceState(nowMillis + 2000, 1000, positionAtIndex(3L), 2L)).thenReturn(generateServiceState(nowMillis + 3000, 2000, null, 3L)).thenReturn(generateServiceState(nowMillis + 1000, 3000, null, 4L)).thenReturn(generateServiceState(nowMillis + 4000, 3000, null, 5L));
    setUpCounters(3);
    setUpMetrics(2);
    setUpProgress(approximateProgressAtIndex(1L));
    progressUpdater.startReportingProgress();
    // The initial update should be sent after 300.
    verify(workUnitClient, timeout(400)).reportWorkItemStatus(argThat(new ExpectedDataflowWorkItemStatus().withCounters(3).withMetrics(2).withProgress(approximateProgressAtIndex(1L)).withReportIndex(1L)));
    setUpCounters(5);
    setUpMetrics(6);
    setUpProgress(approximateProgressAtIndex(2L));
    // The second update should be sent after one second as requested.
    verify(workUnitClient, timeout(1100)).reportWorkItemStatus(argThat(new ExpectedDataflowWorkItemStatus().withCounters(5).withMetrics(6).withProgress(approximateProgressAtIndex(2L)).withDynamicSplitAtPosition(positionAtIndex(3L)).withReportIndex(2L)));
    // After the request is sent, reset cached dynamic split result to null.
    assertNull(progressUpdater.getDynamicSplitResultToReport());
    setUpProgress(approximateProgressAtIndex(3L));
    // The third update should be sent after 2 seconds.
    verify(workUnitClient, timeout(2100)).reportWorkItemStatus(argThat(new ExpectedDataflowWorkItemStatus().withProgress(approximateProgressAtIndex(3L)).withReportIndex(3L)));
    setUpProgress(approximateProgressAtIndex(4L));
    // The fourth update should not respect the suggested report interval.
    // It should be sent before the lease expires
    verify(workUnitClient, timeout(900)).reportWorkItemStatus(argThat(new ExpectedDataflowWorkItemStatus().withProgress(approximateProgressAtIndex(4L)).withReportIndex(4L)));
    progressUpdater.stopReportingProgress();
    assertEquals(5L, progressUpdater.getNextReportIndex());
}

